class ChatLocationBanner extends StatelessWidget { const ChatLocationBanner({super.key, required this.location, required this.onAttach, required this.onClear}); final AppLocation? location; final VoidCallback onAttach, onClear; @override Widget build(BuildContext context) { final value = location; final label = value == null ? 'Attach location for nearby care results' : value.source == LocationSource.manualDistrict ? 'Approximate district attached' : value.source == LocationSource.gps ? 'GPS location attached' : 'Map point attached'; return Card(child: Padding(padding: const EdgeInsets.all(AppTheme.spaceMd), child: Row(children: [const Icon(Icons.location_on_outlined), const SizedBox(width: 8), Expanded(child: Text('$label. Used only for this message.')), TextButton(onPressed: value == null ? onAttach : onClear, child: Text(value == null ? 'Choose' : 'Clear'))]))); } }
